/*
This method transforms a set representation of a tour to a graph path by constructing a new graph path from the set of edges.

@param tour the set of edges in the tour
@param graph the original graph that the tour is on
@return a graph path representing the tour
*/

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Create a new graph path for the tour
    GraphPath<V, E> tourPath = new GraphPath<V, E>();

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the source and destination vertices of the edge
        V sourceVertex = graph.getEdgeSource(edge);
        V destinationVertex = graph.getEdgeTarget(edge);

        // Add the edge to the graph path
        tourPath.addEdge(edge);

        // Update the source and destination vertex of the graph path
        tourPath.setSourceVertex(sourceVertex);
        tourPath.setDestinationVertex(destinationVertex);
    }

    return tourPath;
}
